<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'
import SectionNav from '@/Components/SectionNav.vue'
import { Head, router, useForm } from '@inertiajs/vue3'
import { Building2, CheckCircle2, MapPin, Search } from '@lucide/vue'
import { computed, onMounted, ref } from 'vue'
import { locationDatasetUrl, type LocationDataset } from '@/data/locations'
type Lgu={id:number;psgc_code:string;name:string;province:string|null;region:string|null;active:boolean;circle_id:number|null}
const props=defineProps<{lgus:Lgu[]}>(); const data=ref<LocationDataset|null>(null); const region=ref(''); const province=ref(''); const code=ref(''); const search=ref(''); const removing=ref<Lgu|null>(null); const confirmation=ref(''); const removeError=ref(''); const removingBusy=ref(false)
const regions=computed(()=>data.value?.regions??[]); const currentRegion=computed(()=>regions.value.find(x=>x.name===region.value)??null); const provinces=computed(()=>currentRegion.value?.provinces??[])
const cities=computed(()=>{if(!currentRegion.value)return [];return province.value?provinces.value.find(x=>x.name===province.value)?.municipalities??[]:currentRegion.value.municipalities??[]}); const selected=computed(()=>cities.value.find(x=>x.code===code.value)??null)
const rows=computed(()=>props.lgus.filter(x=>`${x.name} ${x.province} ${x.region} ${x.psgc_code}`.toLowerCase().includes(search.value.toLowerCase()))); const form=useForm({psgc_code:'',name:'',province:'',region:''})
const setRegion=(v:string)=>{region.value=v;province.value='';code.value=''};const setProvince=(v:string)=>{province.value=v;code.value=''}
const submit=()=>{if(!selected.value||!currentRegion.value)return;Object.assign(form,{psgc_code:selected.value.code,name:selected.value.name,province:province.value,region:currentRegion.value.name});form.post(route('admin.lgus.store'),{preserveScroll:true,onSuccess:()=>{region.value='';province.value='';code.value='';form.reset()}})}
const openRemove=(lgu:Lgu)=>{removing.value=lgu;confirmation.value='';removeError.value=''}; const closeRemove=()=>{if(!removingBusy.value)removing.value=null}; const remove=()=>{if(!removing.value||confirmation.value!==removing.value.name){removeError.value='Type the exact LGU name to confirm.';return} removingBusy.value=true;router.delete(route('admin.lgus.destroy',removing.value.id),{data:{confirmation:confirmation.value},preserveScroll:true,onError:errors=>{removeError.value=String(errors.confirmation||errors.remove||'This LGU could not be removed.')},onFinish:()=>{removingBusy.value=false},onSuccess:()=>{removing.value=null}})}
onMounted(async()=>{try{const r=await fetch(locationDatasetUrl,{cache:'force-cache'});if(r.ok)data.value=await r.json()}catch{data.value=null}})
</script>
<template><Head title="LGU registry"/><AuthenticatedLayout><section class="mx-auto max-w-6xl space-y-5 pb-8"><SectionNav section="admin" /><header class="ui-panel p-5 sm:p-6"><p class="text-sm font-bold text-brand-700">System administration</p><div class="mt-2 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><h1 class="text-2xl font-extrabold sm:text-3xl">LGU registry</h1><p class="mt-2 max-w-2xl text-sm leading-6 text-slate-600">Create the official LGU workspace for case routing, staff assignment, and one coordination circle.</p></div><p class="rounded-2xl bg-white px-4 py-3 text-sm shadow-sm"><b class="text-brand-800">{{props.lgus.length}}</b><span class="ml-1 text-slate-500">registered LGUs</span></p></div></header><div class="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><form class="ui-panel p-5" @submit.prevent="submit"><h2 class="font-extrabold">Register an LGU</h2><p class="mt-1 text-sm text-slate-500">Use the official PSGC record. Location data cannot be typed manually.</p><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="text-sm font-bold">Region<select :value="region" class="mt-1.5 block min-h-11 w-full rounded-xl border-slate-300" @change="setRegion(($event.target as HTMLSelectElement).value)"><option value="">Select region</option><option v-for="x in regions" :key="x.code" :value="x.name">{{x.name}}</option></select></label><label class="text-sm font-bold">Province<select :value="province" :disabled="!currentRegion||!provinces.length" class="mt-1.5 block min-h-11 w-full rounded-xl border-slate-300 disabled:bg-slate-100" @change="setProvince(($event.target as HTMLSelectElement).value)"><option value="">{{provinces.length?'Select province':'No province level'}}</option><option v-for="x in provinces" :key="x.code" :value="x.name">{{x.name}}</option></select></label></div><label class="mt-4 block text-sm font-bold">Municipality or city<select v-model="code" :disabled="!currentRegion||(provinces.length>0&&!province)" class="mt-1.5 block min-h-11 w-full rounded-xl border-slate-300 disabled:bg-slate-100"><option value="">Select municipality or city</option><option v-for="x in cities" :key="x.code" :value="x.code">{{x.name}}</option></select></label><p v-if="form.errors.psgc_code" class="mt-2 text-sm text-rose-700">{{form.errors.psgc_code}}</p><button :disabled="!selected||form.processing" class="mt-5 min-h-11 rounded-xl bg-brand-700 px-4 text-sm font-bold text-white disabled:opacity-40">{{form.processing?'Registering':'Register LGU'}}</button></form><aside class="rounded-2xl border border-brand-100 bg-brand-50/60 p-5"><MapPin class="h-5 w-5 text-brand-700"/><h2 class="mt-3 font-extrabold">Registration preview</h2><template v-if="selected"><p class="mt-3 text-lg font-extrabold text-brand-900">{{selected.name}}</p><dl class="mt-4 space-y-3 text-sm"><div><dt class="text-xs font-bold uppercase text-slate-500">Province</dt><dd>{{province||'Not applicable'}}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-500">Region</dt><dd>{{currentRegion?.name}}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-500">PSGC code</dt><dd class="font-mono">{{selected.code}}</dd></div></dl><p class="mt-5 rounded-xl bg-white p-3 text-xs leading-5 text-slate-600">One coordination circle is created. Staff need an LGU assignment before case access.</p></template><p v-else class="mt-3 text-sm leading-6 text-slate-600">Choose a location to review the official record.</p></aside></div><section class="ui-panel p-5"><div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h2 class="text-lg font-extrabold">Registered LGUs</h2><p class="mt-1 text-sm text-slate-500">Each LGU has its own operational boundary.</p></div><label class="relative"><Search class="pointer-events-none absolute left-3 top-3 h-4 w-4 text-slate-500"/><input v-model.trim="search" class="min-h-11 w-full rounded-xl border-slate-300 pl-9 text-sm sm:w-72" placeholder="Search LGU, province, or code"/></label></div><div class="mt-5 grid gap-3 sm:grid-cols-2"><article v-for="x in rows" :key="x.id" class="rounded-2xl border border-slate-200 p-4"><div class="flex justify-between gap-3"><div class="min-w-0"><p class="truncate font-extrabold">{{x.name}}</p><p class="mt-1 text-sm text-slate-600">{{x.province||'No province level'}}</p><p class="text-xs text-slate-500">{{x.region}}</p></div><Building2 class="h-5 w-5 shrink-0 text-brand-700"/></div><div class="mt-4 flex flex-wrap items-center justify-between gap-2 border-t border-slate-100 pt-3"><span class="font-mono text-xs text-slate-500">{{x.psgc_code}}</span><div class="flex items-center gap-2"><span class="inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-bold" :class="x.circle_id?'bg-emerald-50 text-emerald-700':'bg-amber-50 text-amber-800'"><CheckCircle2 class="h-3.5 w-3.5"/>{{x.circle_id?'Circle ready':'Needs review'}}</span><button type="button" class="min-h-9 rounded-lg border border-rose-200 px-3 text-xs font-bold text-rose-700 hover:bg-rose-50" @click="openRemove(x)">Remove</button></div></div></article><p v-if="!rows.length" class="py-8 text-center text-sm text-slate-500 sm:col-span-2">No LGU matches this search.</p></div></section><div v-if="removing" class="fixed inset-0 z-50 grid place-items-end bg-slate-950/40 p-4 sm:place-items-center" role="dialog" aria-modal="true"><form class="w-full max-w-md rounded-2xl bg-white p-5 shadow-2xl" @submit.prevent="remove"><h2 class="text-lg font-extrabold text-slate-900">Remove LGU?</h2><p class="mt-2 text-sm leading-6 text-slate-600">Remove <b>{{removing.name}}</b> only if it was added by mistake and has no staff, cases, reports, or coordination activity.</p><label class="mt-4 block text-sm font-bold text-slate-700">Type <span class="select-all">{{removing.name}}</span> to confirm<input v-model="confirmation" class="mt-1.5 block min-h-11 w-full rounded-xl border-slate-300" autocomplete="off"/></label><p v-if="removeError" class="mt-2 text-sm text-rose-700">{{removeError}}</p><div class="mt-5 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><button type="button" class="min-h-11 rounded-xl border border-slate-300 px-4 text-sm font-bold" @click="closeRemove">Cancel</button><button :disabled="removingBusy||confirmation!==removing.name" class="min-h-11 rounded-xl bg-rose-600 px-4 text-sm font-bold text-white disabled:opacity-40">{{removingBusy?'Removing':'Remove LGU'}}</button></div></form></div></section></AuthenticatedLayout></template>
